1	import { describe, expect, it } from 'vitest';
2	import { SEED_FORM_FIELDS, type FieldSeed, type RuleSeed } from '../src/seed/form-fields';
3	
4	/**
5	 * US-04-AC-26 "Strapi seed content (CO and CL)" (spec 7.1, BR-19, BR-07 exception (c)): the real seed
6	 * definitions carry the rules the front end relies on. The seed is the source of truth for validation
7	 * (ADR-0004, ADR-0014 D2), so removing one of these rules must fail a test. Pure data: no Strapi boot.
8	 *
9	 * The pattern is compiled the way the front end compiles it: `new RegExp('^(?:' + source + ')$')`,
10	 * with no flags (in particular no `u`).
11	 */
12	
13	const LATIN1_CLASS = "^[A-Za-zÀ-ÖØ-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ '.-]*$";
14	const NEW_FULL_NAME_MESSAGE = 'Ingresa tu nombre completo, solo letras (entre 3 y 80 caracteres).';
15	
16	function field(country: 'CO' | 'CL', key: string): FieldSeed {
17	  const found = SEED_FORM_FIELDS[country].find((f) => f.key === key);
18	  if (!found) throw new Error(`The ${country} seed has no "${key}" field`);
19	  return found;
20	}
21	
22	function rulesOf(country: 'CO' | 'CL', key: string, kind: RuleSeed['kind']): RuleSeed[] {
23	  return (field(country, key).rules ?? []).filter((r) => r.kind === kind);
24	}
25	
26	function compiled(country: 'CO' | 'CL', key: string): RegExp {
27	  const rule = rulesOf(country, key, 'pattern')[0];
28	  if (!rule || rule.kind !== 'pattern') throw new Error(`${country} ${key} has no pattern rule`);
29	  return new RegExp('^(?:' + rule.pattern + ')$');
30	}
31	
32	describe.each(['CO', 'CL'] as const)('US-04-AC-26 seed content: fullName (%s)', (country) => {
33	  it('US-04-AC-26 has exactly one pattern rule, with the Latin-1 letter class as written in the spec', () => {
34	    const patterns = rulesOf(country, 'fullName', 'pattern');
35	    expect(patterns).toHaveLength(1);
36	    expect(patterns[0]).toMatchObject({ kind: 'pattern', pattern: LATIN1_CLASS });
37	  });
38	
39	  it('US-04-AC-26 keeps the existing length rules first (minLength 3, maxLength 80) and appends the pattern after them', () => {
40	    const kinds = (field(country, 'fullName').rules ?? []).map((r) => r.kind);
41	    expect(kinds).toEqual(['minLength', 'maxLength', 'pattern']);
42	    expect(field(country, 'fullName').rules).toEqual(expect.arrayContaining([{ kind: 'minLength', value: 3 }, { kind: 'maxLength', value: 80 }]));
43	  });
44	
45	  it('US-04-AC-26 the field errorMessage is the new one', () => {
46	    expect(field(country, 'fullName').errorMessage).toBe(NEW_FULL_NAME_MESSAGE);
47	  });
48	
49	  it('US-04-AC-26 compiled as the front end does (no "u" flag) it accepts "José Núñez-O\'Neil Jr."', () => {
50	    expect(compiled(country, 'fullName').test("José Núñez-O'Neil Jr.")).toBe(true);
51	  });
52	
53	  it.each(['Ana 2', '2Ana', 'Ana_', 'Ana@', '', ' Ana', '-Ana'])('US-04-AC-26 compiled as the front end does it rejects "%s"', (text) => {
54	    expect(compiled(country, 'fullName').test(text)).toBe(false);
55	  });
56	
57	  it('US-04-AC-26 the compiled pattern needs no "u" flag: it compiles without flags and with the anchored wrapper', () => {
58	    expect(() => new RegExp('^(?:' + (rulesOf(country, 'fullName', 'pattern')[0] as { pattern: string }).pattern + ')$')).not.toThrow();
59	  });
60	});
61	
62	describe('US-04-AC-26 seed content: maximum lengths from Strapi', () => {
63	  const rows: ['CO' | 'CL', string, number][] = [
64	    ['CO', 'documentNumber', 10],
65	    ['CL', 'documentNumber', 12],
66	    ['CO', 'plate', 6],
67	    ['CL', 'plate', 6],
68	  ];
69	
70	  it.each(rows)('US-04-AC-26 %s "%s" has exactly one maxLength rule of %i', (country, key, value) => {
71	    const rules = rulesOf(country, key, 'maxLength');
72	    expect(rules).toHaveLength(1);
73	    expect(rules[0]).toMatchObject({ kind: 'maxLength', value });
74	  });
75	
76	  it('US-04-AC-26 the new maxLength rules are appended after the existing rules of the field (existing rules first, in their order)', () => {
77	    expect((field('CO', 'documentNumber').rules ?? []).map((r) => r.kind)).toEqual(['pattern', 'maxLength']);
78	    expect((field('CL', 'documentNumber').rules ?? []).map((r) => r.kind)).toEqual(['pattern', 'rutCheckDigit', 'maxLength']);
79	    expect((field('CO', 'plate').rules ?? []).map((r) => r.kind)).toEqual(['pattern', 'maxLength']);
80	    expect((field('CL', 'plate').rules ?? []).map((r) => r.kind)).toEqual(['pattern', 'maxLength']);
81	  });
82	
